const MILLISECONDS_PER_DAY = 24 * 60 * 60 * 1000;

function isWeekend(date: Date): boolean {
  const day = date.getDay();
  return day === 0 || day === 6;
}

function normalizeDate(date: Date): Date {
  const normalized = new Date(date);
  normalized.setUTCHours(0, 0, 0, 0);
  return normalized;
}

function datesEqual(a: Date, b: Date): boolean {
  return a.getTime() === b.getTime();
}

function isHoliday(date: Date, holidays: readonly Date[]): boolean {
  const normalized = normalizeDate(date);
  return holidays.some(holiday => datesEqual(normalized, normalizeDate(holiday)));
}

export function isBusinessDay(date: Date, holidays?: readonly Date[]): boolean {
  if (isWeekend(date)) {
    return false;
  }
  if (holidays && holidays.length > 0) {
    if (isHoliday(date, holidays)) {
      return false;
    }
  }
  return true;
}

export function normalize(date: Date): Date {
  return normalizeDate(date);
}

function getNextBusinessDay(date: Date, holidays: readonly Date[]): Date {
  const next = new Date(date.getTime() + MILLISECONDS_PER_DAY);
  if (isBusinessDay(next, holidays)) {
    return next;
  }
  return getNextBusinessDay(next, holidays);
}

function getPreviousBusinessDay(date: Date, holidays: readonly Date[]): Date {
  const previous = new Date(date.getTime() - MILLISECONDS_PER_DAY);
  if (isBusinessDay(previous, holidays)) {
    return previous;
  }
  return getPreviousBusinessDay(previous, holidays);
}

export function addBusinessDays(
  startDate: Date,
  businessDays: number,
  holidays: readonly Date[] = []
): Date {
  if (businessDays === 0) {
    return normalizeDate(startDate);
  }

  let current = normalizeDate(startDate);

  if (businessDays > 0) {
    let daysAdded = 0;
    while (daysAdded < businessDays) {
      current = getNextBusinessDay(current, holidays);
      daysAdded++;
    }
  } else {
    let daysAdded = 0;
    const absDays = Math.abs(businessDays);
    while (daysAdded < absDays) {
      current = getPreviousBusinessDay(current, holidays);
      daysAdded++;
    }
  }

  return current;
}

export function getBusinessDaysBetween(
  startDate: Date,
  endDate: Date,
  holidays: readonly Date[] = []
): number {
  const start = normalizeDate(startDate);
  const end = normalizeDate(endDate);

  if (start.getTime() === end.getTime()) {
    return 0;
  }

  const [earlier, later] = start.getTime() < end.getTime() 
    ? [start, end] 
    : [end, start];

  let count = 0;
  let current = new Date(earlier.getTime() + MILLISECONDS_PER_DAY);

  while (current.getTime() <= later.getTime()) {
    if (isBusinessDay(current, holidays)) {
      count++;
    }
    current = new Date(current.getTime() + MILLISECONDS_PER_DAY);
  }

  return count;
}

const MILLISECONDS_PER_DAY = 24 * 60 * 60 * 1000;

export function addDays(date: Date, days: number): Date {
  return new Date(date.getTime() + days * MILLISECONDS_PER_DAY);
}

export function subDays(date: Date, days: number): Date {
  return new Date(date.getTime() - days * MILLISECONDS_PER_DAY);
}

import type { DunningStatus, DunningState, DunningConfig, ActionDescriptor } from './types.js';
import { addBusinessDays, getBusinessDaysBetween } from './businessDays.js';

export const DEFAULT_TIMEOUTS: Record<DunningStatus, number> = {
  ISSUED: -7,
  DUE_SOON: 0,
  OVERDUE: 3,
  GRACE: 7,
  REMINDER_1: 14,
  REMINDER_2: 14,
  FINAL_NOTICE: 7,
  SUSPENDED: 30,
  WRITTEN_OFF: Infinity,
  PAID: Infinity,
  PAUSED: Infinity,
  CANCELLED: Infinity
};

export const ESCALATION_ORDER: DunningStatus[] = [
  'ISSUED',
  'DUE_SOON',
  'OVERDUE',
  'GRACE',
  'REMINDER_1',
  'REMINDER_2',
  'FINAL_NOTICE',
  'SUSPENDED',
  'WRITTEN_OFF'
];

export const TERMINAL_STATES: DunningStatus[] = ['PAID', 'WRITTEN_OFF', 'CANCELLED'];

export const PAUSEABLE_STATES: DunningStatus[] = [
  'OVERDUE',
  'GRACE',
  'REMINDER_1',
  'REMINDER_2',
  'FINAL_NOTICE',
  'SUSPENDED'
];

export function getTimeout(status: DunningStatus, config: DunningConfig): number {
  if (config.timeouts && config.timeouts[status] !== undefined) {
    return config.timeouts[status]!;
  }
  return DEFAULT_TIMEOUTS[status];
}

export function getHolidays(config: DunningConfig): readonly Date[] {
  return config.holidays ?? [];
}

export function calculateTargetDate(
  dueDate: Date,
  status: DunningStatus,
  config: DunningConfig
): Date {
  const timeout = getTimeout(status, config);
  const holidays = getHolidays(config);

  if (timeout < 0) {
    return addBusinessDays(dueDate, timeout, holidays);
  }

  return addBusinessDays(dueDate, timeout, holidays);
}

export function shouldTransition(
  currentStatus: DunningStatus,
  stateEnteredAt: Date,
  now: Date,
  config: DunningConfig,
  dueDate: Date,
  pausedFrom?: DunningStatus,
  pausedElapsed?: number
): boolean {
  if (TERMINAL_STATES.includes(currentStatus)) {
    return false;
  }

  const timeout = getTimeout(currentStatus, config);

  if (timeout === Infinity) {
    return false;
  }

  const holidays = getHolidays(config);

  let elapsed: number;

  if (pausedFrom !== undefined && pausedElapsed !== undefined) {
    const currentElapsed = getBusinessDaysBetween(stateEnteredAt, now, holidays);
    elapsed = pausedElapsed + currentElapsed;
  } else {
    elapsed = getBusinessDaysBetween(stateEnteredAt, now, holidays);
  }

  if (currentStatus === 'ISSUED') {
    const targetDate = calculateTargetDate(dueDate, currentStatus, config);
    return now >= targetDate;
  }

  if (currentStatus === 'DUE_SOON') {
    return now >= dueDate;
  }

  return elapsed >= timeout;
}

export function getNextStatus(currentStatus: DunningStatus): DunningStatus | null {
  const currentIndex = ESCALATION_ORDER.indexOf(currentStatus);
  if (currentIndex === -1 || currentIndex === ESCALATION_ORDER.length - 1) {
    return null;
  }
  return ESCALATION_ORDER[currentIndex + 1];
}

export function canPause(status: DunningStatus): boolean {
  return PAUSEABLE_STATES.includes(status);
}

export function getResumeStatus(state: DunningState): DunningStatus {
  return state.pausedFrom ?? state.status;
}

export function getResumeElapsed(state: DunningState): number | undefined {
  return state.pausedElapsed;
}

export function getPausedElapsed(
  stateEnteredAt: Date,
  now: Date,
  config: DunningConfig
): number {
  const holidays = getHolidays(config);
  return getBusinessDaysBetween(stateEnteredAt, now, holidays);
}

export function getActionsForTransition(_fromStatus: DunningStatus, toStatus: DunningStatus): ActionDescriptor[] {
  const actions: ActionDescriptor[] = [];

  switch (toStatus) {
    case 'DUE_SOON':
      actions.push({ type: 'send_email', template: 'due_soon_reminder' });
      break;
    case 'REMINDER_1':
      actions.push({ type: 'send_email', template: 'first_reminder' });
      break;
    case 'REMINDER_2':
      actions.push({ type: 'send_email', template: 'second_reminder' });
      break;
    case 'FINAL_NOTICE':
      actions.push({ type: 'send_email', template: 'final_warning' });
      break;
    case 'SUSPENDED':
      actions.push({ type: 'suspend_service' });
      actions.push({ type: 'send_email', template: 'service_suspended' });
      break;
    case 'WRITTEN_OFF':
      actions.push({ type: 'send_email', template: 'written_off_notice' });
      break;
  }

  return actions;
}

export function createState(
  status: DunningStatus,
  dueDate: Date,
  now: Date,
  config: DunningConfig,
  pausedFrom?: DunningStatus,
  pausedElapsed?: number
): DunningState {
  return {
    status,
    dueDate,
    stateEnteredAt: now,
    config,
    ...(pausedFrom !== undefined && { pausedFrom }),
    ...(pausedElapsed !== undefined && { pausedElapsed })
  };
}

export type {
  DunningStatus,
  EventType,
  ActionType,
  ActionDescriptor,
  DunningConfig,
  DunningState,
  DunningEvent,
  ProcessResult
} from './types.js';

import type { DunningConfig, DunningState, DunningEvent, ProcessResult } from './types.js';
import {
  createState,
  shouldTransition,
  getNextStatus,
  getActionsForTransition,
  TERMINAL_STATES,
  PAUSEABLE_STATES
} from './dunning.js';
import { getBusinessDaysBetween } from './businessDays.js';

export function createInstance(
  dueDate: Date,
  config?: Partial<DunningConfig>
): DunningState {
  const normalizedDueDate = new Date(dueDate);
  normalizedDueDate.setUTCHours(0, 0, 0, 0);

  const fullConfig: DunningConfig = {
    timeouts: config?.timeouts,
    holidays: config?.holidays
  };

  return createState('ISSUED', normalizedDueDate, new Date(), fullConfig);
}

function normalizeDate(date: Date): Date {
  const normalized = new Date(date);
  normalized.setUTCHours(0, 0, 0, 0);
  return normalized;
}

function handlePaymentReceived(
  state: DunningState,
  now: Date
): ProcessResult {
  const currentStatus = state.status;

  if (TERMINAL_STATES.includes(currentStatus)) {
    return { state, actions: [] };
  }

  if (currentStatus === 'SUSPENDED') {
    return {
      state: createState('PAID', state.dueDate, now, state.config),
      actions: [{ type: 'resume_service' }]
    };
  }

  return {
    state: createState('PAID', state.dueDate, now, state.config),
    actions: []
  };
}

function handleInvoiceCancelled(
  state: DunningState,
  now: Date
): ProcessResult {
  const currentStatus = state.status;

  if (TERMINAL_STATES.includes(currentStatus)) {
    return { state, actions: [] };
  }

  if (currentStatus === 'SUSPENDED') {
    return {
      state: createState('CANCELLED', state.dueDate, now, state.config),
      actions: [{ type: 'resume_service' }]
    };
  }

  return {
    state: createState('CANCELLED', state.dueDate, now, state.config),
    actions: []
  };
}

function handleDunningPaused(
  state: DunningState,
  now: Date
): ProcessResult {
  const currentStatus = state.status;

  if (!PAUSEABLE_STATES.includes(currentStatus)) {
    return { state, actions: [] };
  }

  const pausedElapsed = getBusinessDaysBetween(state.stateEnteredAt, now, state.config.holidays ?? []);

  return {
    state: createState('PAUSED', state.dueDate, now, state.config, currentStatus, pausedElapsed),
    actions: []
  };
}

function handleDunningResumed(
  state: DunningState,
  now: Date
): ProcessResult {
  const currentStatus = state.status;

  if (currentStatus !== 'PAUSED') {
    return { state, actions: [] };
  }

  const resumeStatus = state.pausedFrom ?? state.status;

  return {
    state: createState(resumeStatus, state.dueDate, now, state.config),
    actions: []
  };
}

function handleManualAdvance(
  state: DunningState,
  now: Date
): ProcessResult {
  const currentStatus = state.status;

  if (TERMINAL_STATES.includes(currentStatus)) {
    return { state, actions: [] };
  }

  if (currentStatus === 'PAUSED') {
    return { state, actions: [] };
  }

  const nextStatus = getNextStatus(currentStatus);

  if (!nextStatus) {
    return { state, actions: [] };
  }

  const actions = getActionsForTransition(currentStatus, nextStatus);

  return {
    state: createState(nextStatus, state.dueDate, now, state.config),
    actions
  };
}

export function process(
  state: DunningState,
  event: DunningEvent,
  now: Date
): ProcessResult {
  const currentStatus = state.status;
  const config = state.config;
  const normalizedNow = normalizeDate(now);

  if (TERMINAL_STATES.includes(currentStatus)) {
    return { state, actions: [] };
  }

  switch (event.type) {
    case 'payment_received':
      return handlePaymentReceived(state, normalizedNow);

    case 'invoice_cancelled':
      return handleInvoiceCancelled(state, normalizedNow);

    case 'dunning_paused':
      return handleDunningPaused(state, normalizedNow);

    case 'dunning_resumed':
      return handleDunningResumed(state, normalizedNow);

    case 'manual_advance':
      return handleManualAdvance(state, normalizedNow);

    case 'tick': {
      const shouldMove = shouldTransition(
        currentStatus,
        state.stateEnteredAt,
        normalizedNow,
        config,
        state.dueDate,
        state.pausedFrom,
        state.pausedElapsed
      );

      if (shouldMove) {
        const nextStatus = getNextStatus(currentStatus);

        if (nextStatus) {
          const actions = getActionsForTransition(currentStatus, nextStatus);
          const newState = createState(
            nextStatus,
            state.dueDate,
            normalizedNow,
            config
          );

          return { state: newState, actions };
        }
      }

      return { state, actions: [] };
    }

    default:
      return { state, actions: [] };
  }
}

export type DunningStatus =
  | "ISSUED" | "DUE_SOON" | "OVERDUE" | "GRACE"
  | "REMINDER_1" | "REMINDER_2" | "FINAL_NOTICE"
  | "SUSPENDED" | "WRITTEN_OFF" | "PAID" | "PAUSED" | "CANCELLED"

export type EventType =
  | "tick" | "payment_received" | "invoice_cancelled"
  | "dunning_paused" | "dunning_resumed" | "manual_advance"

export type ActionType = "send_email" | "suspend_service" | "resume_service"

export interface ActionDescriptor {
  type: ActionType
  template?: string
}

export interface DunningConfig {
  timeouts?: Partial<Record<DunningStatus, number>>
  holidays?: Date[]
}

export interface DunningState {
  status: DunningStatus
  dueDate: Date
  stateEnteredAt: Date
  config: DunningConfig
  pausedFrom?: DunningStatus
  pausedElapsed?: number
}

export interface DunningEvent {
  type: EventType
}

export interface ProcessResult {
  state: DunningState
  actions: ActionDescriptor[]
}

import { describe, it, expect } from 'vitest';
import { addBusinessDays, getBusinessDaysBetween, isBusinessDay, normalize } from '../src/businessDays.js';

describe('Business Days Utility', () => {
  describe('addBusinessDays', () => {
    it('should add 0 business days', () => {
      const start = new Date('2024-01-01'); // Monday
      const result = addBusinessDays(start, 0);
      expect(result.getDate()).toBe(1);
    });

    it('should add 1 business day to Monday', () => {
      const start = new Date('2024-01-01'); // Monday
      const result = addBusinessDays(start, 1);
      expect(result.getDate()).toBe(2); // Tuesday
    });

    it('should skip weekend when adding business days', () => {
      const friday = new Date('2024-01-05'); // Friday
      const result = addBusinessDays(friday, 1);
      expect(result.getDate()).toBe(8); // Next Monday
    });

    it('should skip entire weekend when adding multiple days', () => {
      const friday = new Date('2024-01-05'); // Friday
      const result = addBusinessDays(friday, 3);
      expect(result.getDate()).toBe(10); // Wednesday
    });

    it('should handle starting on Saturday', () => {
      const saturday = new Date('2024-01-06'); // Saturday
      const result = addBusinessDays(saturday, 1);
      expect(result.getDate()).toBe(8); // Monday
    });

    it('should handle starting on Sunday', () => {
      const sunday = new Date('2024-01-07'); // Sunday
      const result = addBusinessDays(sunday, 1);
      expect(result.getDate()).toBe(8); // Monday
    });
  });

  describe('addBusinessDays with holidays', () => {
    it('should skip holidays', () => {
      const monday = new Date('2024-01-01'); // Monday
      const holidays = [new Date('2024-01-02')]; // Tuesday is a holiday
      const result = addBusinessDays(monday, 1, holidays);
      expect(result.getDate()).toBe(3); // Wednesday
    });

    it('should skip multiple holidays', () => {
      const monday = new Date('2024-01-01'); // Monday
      const holidays = [
        new Date('2024-01-02'), // Tuesday
        new Date('2024-01-03')  // Wednesday
      ];
      const result = addBusinessDays(monday, 1, holidays);
      expect(result.getDate()).toBe(4); // Thursday
    });

    it('should skip holiday on Friday and not double-count weekend', () => {
      const thursday = new Date('2024-01-04'); // Thursday
      const holidays = [new Date('2024-01-05')]; // Friday is a holiday
      const result = addBusinessDays(thursday, 1, holidays);
      expect(result.getDate()).toBe(8); // Monday
    });
  });

  describe('getBusinessDaysBetween', () => {
    it('should return 0 for same day', () => {
      const date = new Date('2024-01-01');
      const result = getBusinessDaysBetween(date, date);
      expect(result).toBe(0);
    });

    it('should count 1 business day between Monday and Tuesday', () => {
      const monday = new Date('2024-01-01');
      const tuesday = new Date('2024-01-02');
      const result = getBusinessDaysBetween(monday, tuesday);
      expect(result).toBe(1);
    });

    it('should exclude weekend in count', () => {
      const friday = new Date('2024-01-05');
      const monday = new Date('2024-01-08');
      const result = getBusinessDaysBetween(friday, monday);
      expect(result).toBe(1); // Only counts Monday
    });

    it('should count full week as 5 days', () => {
      const monday = new Date('2024-01-01');
      const nextMonday = new Date('2024-01-08');
      const result = getBusinessDaysBetween(monday, nextMonday);
      expect(result).toBe(5);
    });
  });

  describe('getBusinessDaysBetween with holidays', () => {
    it('should exclude holidays from count', () => {
      const monday = new Date('2024-01-01');
      const wednesday = new Date('2024-01-03');
      const holidays = [new Date('2024-01-02')]; // Tuesday is a holiday
      const result = getBusinessDaysBetween(monday, wednesday, holidays);
      expect(result).toBe(1); // Only Monday counts
    });
  });

  describe('isBusinessDay', () => {
    it('should return true for Monday', () => {
      const monday = new Date('2024-01-01');
      expect(isBusinessDay(monday)).toBe(true);
    });

    it('should return false for Saturday', () => {
      const saturday = new Date('2024-01-06');
      expect(isBusinessDay(saturday)).toBe(false);
    });

    it('should return false for Sunday', () => {
      const sunday = new Date('2024-01-07');
      expect(isBusinessDay(sunday)).toBe(false);
    });

    it('should return false for holiday', () => {
      const monday = new Date('2024-01-01');
      const holidays = [new Date('2024-01-01')];
      expect(isBusinessDay(monday, holidays)).toBe(false);
    });
  });

  describe('normalize', () => {
    it('should normalize to midnight UTC', () => {
      const date = new Date('2024-01-01T15:30:00');
      const normalized = normalize(date);
      expect(normalized.getUTCHours()).toBe(0);
      expect(normalized.getUTCMinutes()).toBe(0);
      expect(normalized.getUTCSeconds()).toBe(0);
      expect(normalized.getUTCMilliseconds()).toBe(0);
    });
  });
});

